isting WordPress drafts were preserved.','wordpress-news-bot'),'draft_connection'=>__('Complete the OpenAI connection before creating a draft.','wordpress-news-bot'),'draft_created'=>__('The selected WordPress draft was created.','wordpress-news-bot'),'draft_error'=>__('The draft could not be created. No post was published.','wordpress-news-bot')];
        if(!isset($messages[$code]))return;$detail=$this->takeAdminNotice();$error=in_array($code,['error','decrypt','source_error','source_duplicate','source_diagnostic_error','db_repair_required','db_repair_failed','draft_error','draft_connection'],true);echo '<div class="notice '.($error?'notice-error':'notice-success').' is-dismissible"><p>'.esc_html($messages[$code]);if($detail!=='')echo '<br>'.esc_html($detail);if($code==='draft_connection')echo ' <a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-settings')).'">'.esc_html__('Open Settings','wordpress-news-bot').'</a>';if($code==='draft_created'&&($postId=absint($_GET['wpnb_post_id']??0)))echo ' <a class="button" href="'.esc_url(get_edit_post_link($postId,'')).'">'.esc_html__('Edit WordPress Draft','wordpress-news-bot').'</a>';echo '</p></div>';
