        $settings=$this->settingsValue();$used=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(ai_requests,0) FROM '.Support::table('daily_usage').' WHERE usage_date=%s',gmdate('Y-m-d')));$quota=(int)($settings['daily_ai_quota']??25);$cards=[[__('Active sources','wordpress-news-bot'),(string)(int)$wpdb->get_var('SELECT COUNT(*) FROM '.Support::table('sources').' WHERE active=1')],[__('Pending news','wordpress-news-bot'),(string)(int)$wpdb->get_var("SELECT COUNT(*) FROM ".Support::table('feed_items')." WHERE status IN ('new','review','error')")],[__('News fetched today','wordpress-news-bot'),(string)(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Support::table('feed_items').' WHERE created_at>=%s',gmdate('Y-m-d 00:00:00')) )],[__('Created drafts','wordpress-news-bot'),(string)(int)$wpdb->get_var("SELECT COUNT(*) FROM ".Support::table('feed_items')." WHERE status='draft_created'")],[__('Failed operations','wordpress-news-bot'),(string)(int)$wpdb->get_var("SELECT COUNT(*) FROM ".Support::table('logs')." WHERE level='error'")],[__('Remaining daily quota','wordpress-news-bot'),(string)max(0,$quota-$used)]];
        echo '<div class="wpnb-grid">';foreach($cards as[$label,$value])echo '<div class="wpnb-card"><h2>'.esc_html($label).'</h2><div class="wpnb-status">'.esc_html($value).'</div></div>';echo '</div><div class="wpnb-actions">';$this->fetchAllForm(__('Fetch News Now','wordpress-news-bot'));echo '<a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-pool')).'">'.esc_html__('Open News Pool','wordpress-news-bot').'</a><a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-pool')).'">'.esc_html__('Start Creating Drafts','wordpress-news-bot').'</a></div>'; $this->end();
    }
    public function setupWizard():void
    {
        $this->requireManage(); $step=min(5,max(1,absint($_GET['step']??1))); $titles=[1=>__('OpenAI connection','wordpress-news-bot'),2=>__('Content generation','wordpress-news-bot'),3=>__('Usage limits','wordpress-news-bot'),4=>__('First RSS source','wordpress-news-bot'),5=>__('Setup summary','wordpress-news-bot')]; $this->begin(__('Setup Wizard','wordpress-news-bot')); $this->notice(); echo '<p>'.esc_html(sprintf(__('Step %1$d of 5: %2$s','wordpress-news-bot'),$step,$titles[$step])).'</p><div class="wpnb-card">';
        if($step===1){$this->connectionCard(true);}elseif($step===2){$this->settingsForm('content');}elseif($step===3){$this->settingsForm('limits');}elseif($step===4){$this->sourceForm(true);}else{echo '<p>'.esc_html__('Your settings can be changed at any time. Generated posts always remain drafts.','wordpress-news-bot').'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_finish_setup');echo '<input type="hidden" name="action" value="wpnb_finish_setup">';submit_button(__('Finish Setup','wordpress-news-bot'),'primary','submit',false);echo '</form>';}
        echo '</div><div class="wpnb-actions">';if($step<5)echo '<a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=wpnb-setup&step='.($step+1))).'">'.esc_html__('Next','wordpress-news-bot').'</a>';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_skip_setup');echo '<input type="hidden" name="action" value="wpnb_skip_setup"><button class="button">'.esc_html__('Skip setup','wordpress-news-bot').'</button></form></div>'; $this->end();
    }
