    private function automationCard():void { $s=$this->settingsValue();if(defined('DISABLE_WP_CRON')&&DISABLE_WP_CRON){echo '<p>'.esc_html__('Automatic news fetching is disabled. Manual news fetching is available.','wordpress-news-bot').'</p>';$this->fetchAllForm(__('Fetch from All Active Sources','wordpress-news-bot'));return;} $next=wp_next_scheduled('wpnb_poll_sources');echo '<p>'.esc_html(!empty($s['cron_enabled'])?__('Automation is enabled.','wordpress-news-bot'):__('Automation is disabled.','wordpress-news-bot')).'</p><p>'.esc_html(sprintf(__('Last run: %s','wordpress-news-bot'),get_option('wpnb_last_automation_run',__('Never','wordpress-news-bot')))).'<br>'.esc_html(sprintf(__('Next run: %s','wordpress-news-bot'),$next?wp_date('Y-m-d H:i:s',$next):__('Not scheduled','wordpress-news-bot'))).'</p><form method="post" action="options.php">';settings_fields('wpnb_settings_group');foreach($s as$key=>$value)if($key!=='cron_enabled')echo '<input type="hidden" name="wpnb_settings['.esc_attr($key).']" value="'.esc_attr((string)$value).'">';echo '<label><input type="checkbox" name="wpnb_settings[cron_enabled]" value="1" '.checked((int)($s['cron_enabled']??0),1,false).'> '.esc_html__('Enable automation','wordpress-news-bot').'</label><p>';submit_button(__('Save Automation','wordpress-news-bot'),'secondary','submit',false);echo '</p></form>';$this->fetchAllForm(__('Fetch from All Active Sources','wordpress-news-bot')); }
    public function sources():void
    {
        $this->requireManage();
        global $wpdb;
        $sourceHealth=(new DatabaseHealth($wpdb))->sourceReady();$rows=$sourceHealth['ready']?$wpdb->get_results('SELECT * FROM '.Support::table('sources').' ORDER BY id DESC'):[];
        $editId=absint($_GET['wpnb_edit']??0);
        $deleteId=absint($_GET['wpnb_delete_confirm']??0);
        $edit=$sourceHealth['ready']&&$editId?(array)$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Support::table('sources').' WHERE id=%d LIMIT 1',$editId),ARRAY_A):[];
        $formState=(array)get_transient($this->sourceFormKey());if(!$edit&&isset($formState['input'])&&is_array($formState['input']))$edit=$formState['input'];
        $this->begin(__('News Sources','wordpress-news-bot'));
        $this->notice();
        $nextOffset=absint($_GET['wpnb_import_offset']??0);if($nextOffset>0){echo '<div class="notice notice-info inline"><p>'.esc_html__('The next source batch is ready.','wordpress-news-bot').'</p>';$this->fetchAllForm(__('Continue Fetching News','wordpress-news-bot'),$nextOffset);echo '</div>';}
        $savedSourceId=absint($_GET['wpnb_source_id']??0);if($savedSourceId>0){echo '<div class="notice notice-success inline"><p>'.esc_html__('Source saved. Fetch news now.','wordpress-news-bot').'</p>';$this->fetchSourceForm($savedSourceId,__('Fetch News Now','wordpress-news-bot'),'button button-primary');echo '</div>';}
        if(!$sourceHealth['ready'])echo '<div class="notice notice-error"><p>'.esc_html__('The source database schema requires repair. The saved connection test will be kept while you repair it.','wordpress-news-bot').' <a href="'.esc_url(admin_url('admin.php?page=wpnb-health')).'">'.esc_html__('Open Database Health','wordpress-news-bot').'</a></p></div>';
        $recovery=(array)get_option('wpnb_source_recovery_required',[]);$recoveryHash=$recovery?hash('sha256',Support::json($recovery)):'';$ack=(string)get_user_meta(get_current_user_id(),'wpnb_source_recovery_ack',true);if($recovery&&$ack!==$recoveryHash){$message=($recovery['reason']??'')==='missing_snapshot'?__('The previous source migration did not complete. Source information could not be restored automatically. Please add the source again.','wordpress-news-bot'):__('The source migration could not be completed. Existing source records were restored from the migration journal. Please review the error log before trying again.','wordpress-news-bot');echo '<div class="notice notice-error"><p>'.esc_html($message).'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_dismiss_recovery');echo '<input type="hidden" name="action" value="wpnb_dismiss_recovery"><button class="button">'.esc_html__('Dismiss this notice','wordpress-news-bot').'</button></form><p></p></div>';}

        if($sourceHealth['ready']&&$deleteId){
            $source=(array)$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Support::table('sources').' WHERE id=%d LIMIT 1',$deleteId),ARRAY_A);
            if($source){$summary=(new SourceService($wpdb))->deletionSummary($deleteId);echo '<div class="wpnb-card"><h2>'.esc_html__('Delete news source','wordpress-news-bot').'</h2><p><strong>'.esc_html__('Are you sure you want to delete this news source?','wordpress-news-bot').'</strong></p><p>'.esc_html(sprintf(__('Pending news: %d','wordpress-news-bot'),$summary['pending'])).'<br>'.esc_html(sprintf(__('Processed news: %d','wordpress-news-bot'),$summary['processed'])).'<br>'.esc_html(sprintf(__('Created WordPress drafts: %d','wordpress-news-bot'),$summary['drafts'])).'</p><p>'.esc_html__('Existing WordPress posts and drafts will not be deleted.','wordpress-news-bot').'</p><div class="wpnb-actions"><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_delete_source_'.$deleteId);echo '<input type="hidden" name="action" value="wpnb_delete_source"><input type="hidden" name="source_id" value="'.esc_attr((string)$deleteId).'"><button class="button button-primary wpnb-danger">'.esc_html__('Delete','wordpress-news-bot').'</button></form><a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-sources')).'">'.esc_html__('Cancel','wordpress-news-bot').'</a></div></div>';}
        }

        echo '<div class="wpnb-actions" style="margin:12px 0">';$this->fetchAllForm(__('Fetch from All Active Sources','wordpress-news-bot'));echo '<form id="wpnb-bulk-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="wpnb-actions">';wp_nonce_field('wpnb_bulk_sources');echo '<input type="hidden" name="action" value="wpnb_bulk_sources"><label class="screen-reader-text" for="wpnb-bulk-action">'.esc_html__('Bulk actions','wordpress-news-bot').'</label><select id="wpnb-bulk-action" name="bulk_action" required><option value="">'.esc_html__('Bulk actions','wordpress-news-bot').'</option><option value="activate">'.esc_html__('Activate','wordpress-news-bot').'</option><option value="deactivate">'.esc_html__('Deactivate','wordpress-news-bot').'</option><option value="delete">'.esc_html__('Delete','wordpress-news-bot').'</option></select><button class="button" onclick="if(this.form.bulk_action.value===\'delete\'&&!confirm(\''.esc_js(__('Are you sure you want to delete the selected news sources?','wordpress-news-bot')).'\'))return false;">'.esc_html__('Apply','wordpress-news-bot').'</button></form></div>';
        echo '<table class="widefat striped wpnb-sources-table"><thead><tr><td class="check-column"><input type="checkbox" onclick="document.querySelectorAll(\'.wpnb-source-check\').forEach(e=>e.checked=this.checked)"></td><th>'.esc_html__('Source name','wordpress-news-bot').'</th><th>'.esc_html__('RSS/Atom URL','wordpress-news-bot').'</th><th>'.esc_html__('Allowed domain','wordpress-news-bot').'</th><th>'.esc_html__('Linked category','wordpress-news-bot').'</th><th>'.esc_html__('Status','wordpress-news-bot').'</th><th>'.esc_html__('Last check','wordpress-news-bot').'</th><th>'.esc_html__('Result','wordpress-news-bot').'</th><th>'.esc_html__('Actions','wordpress-news-bot').'</th></tr></thead><tbody>';
        if(!$rows)echo '<tr><td colspan="9">'.esc_html__('No news sources have been added yet.','wordpress-news-bot').'</td></tr>';
        foreach($rows as$row){$id=(int)$row->id;$category=$row->category_id?get_cat_name((int)$row->category_id):__('Unassigned','wordpress-news-bot');echo '<tr><th class="check-column"><input class="wpnb-source-check" form="wpnb-bulk-form" type="checkbox" name="source_ids[]" value="'.esc_attr((string)$id).'"></th><td data-label="'.esc_attr__('Source name','wordpress-news-bot').'">'.esc_html($row->name).'</td><td class="wpnb-source-url" data-label="'.esc_attr__('RSS/Atom URL','wordpress-news-bot').'">'.esc_html($row->feed_url).'</td><td data-label="'.esc_attr__('Allowed domain','wordpress-news-bot').'">'.nl2br(esc_html((string)$row->allowed_domains)).'</td><td data-label="'.esc_attr__('Linked category','wordpress-news-bot').'">'.esc_html($category).'</td><td data-label="'.esc_attr__('Status','wordpress-news-bot').'">'.esc_html($row->active?__('Active','wordpress-news-bot'):__('Inactive','wordpress-news-bot')).'</td><td data-label="'.esc_attr__('Last check','wordpress-news-bot').'">'.esc_html($row->last_checked_at?:__('Never','wordpress-news-bot')).'</td><td data-label="'.esc_attr__('Result','wordpress-news-bot').'">'.esc_html($row->last_result?:($row->last_error?:__('Not tested','wordpress-news-bot'))).'</td><td data-label="'.esc_attr__('Actions','wordpress-news-bot').'"><div class="wpnb-source-actions">';
            if($row->active)$this->fetchSourceForm($id,__('Fetch News','wordpress-news-bot'));
            $this->sourceActionForm('wpnb_test_source','wpnb_test_source_'.$id,$id,__('Test','wordpress-news-bot'));
            echo '<a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-sources&wpnb_edit='.$id.'#wpnb-source-form')).'">'.esc_html__('Edit','wordpress-news-bot').'</a>';
