        }
        echo '</tbody></table><div id="wpnb-source-form" class="wpnb-card" style="margin-top:20px"><h2>'.esc_html(!empty($edit['id'])?__('Edit source','wordpress-news-bot'):__('Add source','wordpress-news-bot')).'</h2>';if(!empty($formState['result']))$this->sourceTestResult((array)$formState['result']);$this->sourceForm(false,$edit,(string)($formState['token']??''));echo '</div>';$this->end();
    }
    private function sourceActionForm(string$action,string$nonce,int$id,string$label):void { echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field($nonce);echo '<input type="hidden" name="action" value="'.esc_attr($action).'"><input type="hidden" name="source_id" value="'.esc_attr((string)$id).'"><button class="button">'.esc_html($label).'</button></form>'; }
