    private function sourceForm(bool$wizard,array$source=[],string$testToken=''):void
    {
        $id=(int)($source['id']??0);$active=$source?(!empty($source['active'])):true;$importImages=$source?(!empty($source['import_images'])):true;$draftWithoutImage=$source?(!empty($source['draft_without_image'])):true;$useOgImage=!empty($source['use_og_image']);
        $feedUrl=(string)($source['feed_url']??'');$parts=$feedUrl!==''?wp_parse_url($feedUrl):[];$primaryHost=SourceUrl::normalizeHost((string)($parts['host']??''));$automaticHosts=[$primaryHost];if(str_starts_with($primaryHost,'www.')&&count(explode('.',substr($primaryHost,4)))>=3)$automaticHosts[]=substr($primaryHost,4);$advancedDomains=array_values(array_diff(array_filter(array_map('trim',preg_split('/[\r\n,]+/',(string)($source['allowed_domains']??''))?:[])),$automaticHosts));
        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wpnb_save_source');echo '<input type="hidden" name="source_id" value="'.esc_attr((string)$id).'"><input type="hidden" name="return_page" value="'.esc_attr($wizard?'wpnb-setup':'wpnb-sources').'"><input type="hidden" name="source_test_token" value="'.esc_attr($testToken).'">';
        echo '<div class="wpnb-field"><label for="wpnb-source-name">'.esc_html__('Source name','wordpress-news-bot').'</label><input id="wpnb-source-name" required name="name" value="'.esc_attr((string)($source['name']??'')).'" class="regular-text"></div>';
        echo '<div class="wpnb-field"><label for="wpnb-feed-url">'.esc_html__('RSS/Atom URL','wordpress-news-bot').'</label><input id="wpnb-feed-url" required type="url" name="feed_url" value="'.esc_attr($feedUrl).'" placeholder="https://example.com/feed" class="regular-text"></div>';
        echo '<div class="wpnb-field"><label><input type="checkbox" name="import_images" value="1" '.checked($importImages,true,false).'> '.esc_html__('Import news images','wordpress-news-bot').'</label><p class="description">'.esc_html__('Images are copied securely to the WordPress Media Library; remote images are never hotlinked.','wordpress-news-bot').'</p></div>';
        echo '<div class="wpnb-field"><label><input type="checkbox" name="draft_without_image" value="1" '.checked($draftWithoutImage,true,false).'> '.esc_html__('Create a draft when no image is found','wordpress-news-bot').'</label></div>';
        echo '<details class="wpnb-field"><summary><strong>'.esc_html__('Advanced Settings','wordpress-news-bot').'</strong></summary><p><label for="wpnb-allowed-domains">'.esc_html__('Additional redirect domains','wordpress-news-bot').'</label><input id="wpnb-allowed-domains" name="allowed_domains" value="'.esc_attr(implode("\n",$advancedDomains)).'" placeholder="cdn.example.com" class="regular-text"></p><p class="description">'.esc_html__('The primary allowed host is detected automatically from the RSS URL. Add only extra trusted redirect domains here.','wordpress-news-bot').'</p><p><label><input type="checkbox" name="use_og_image" value="1" '.checked($useOgImage,true,false).'> '.esc_html__('Check the news page og:image field','wordpress-news-bot').'</label></p><p class="description">'.esc_html__('This option visits each news article page when the feed has no image. Enable it only for trusted sources.','wordpress-news-bot').'</p></details>';
        echo '<div class="wpnb-field"><label for="wpnb-category">'.esc_html__('WordPress category','wordpress-news-bot').'</label>';wp_dropdown_categories(['id'=>'wpnb-category','name'=>'category_id','show_option_none'=>__('Unassigned','wordpress-news-bot'),'option_none_value'=>'0','hide_empty'=>0,'selected'=>(int)($source['category_id']??0)]);echo '</div>';
        echo '<div class="wpnb-field"><label><input type="checkbox" name="active" value="1" '.checked($active,true,false).'> '.esc_html__('Active','wordpress-news-bot').'</label></div><div class="wpnb-actions"><button class="button" name="action" value="wpnb_test_source">'.esc_html__('Test Before Saving','wordpress-news-bot').'</button><button class="button button-primary" name="action" value="wpnb_save_source">'.esc_html($id?__('Update Source','wordpress-news-bot'):__('Save Source','wordpress-news-bot')).'</button></div></form>';
    }
    public function saveSource():void { $this->requirePostAction('wpnb_save_source');global$wpdb;$id=absint($_POST['source_id']??0);$input=$this->sourceInput();try{$verified=$this->verifiedSourceTest($input);$savedId=(new SourceService($wpdb))->save($input,$id,$verified);delete_transient($this->sourceFormKey());delete_option('wpnb_source_recovery_required');delete_user_meta(get_current_user_id(),'wpnb_source_recovery_ack');$return=sanitize_key($_POST['return_page']??'wpnb-sources');$this->redirect($return==='wpnb-setup'?'wpnb-setup&step=5':'wpnb-sources&wpnb_source_id='.$savedId,$id?'source_updated':'source_saved');}catch(\DomainException$e){$this->retainSourceForm($input);$this->logSourceError('source_save_duplicate',$e);$this->redirect('wpnb-sources','source_duplicate');}catch(SourceTestException$e){$this->retainSourceForm($input);$this->handleSourceDiagnostic($e,'source_save_failed');}catch(\Throwable$e){$this->retainSourceForm($input);$this->logSourceError('source_save_failed',$e);$this->redirect('wpnb-sources','source_error');} }
    public function testSource():void { $id=absint($_POST['source_id']??0);$this->requirePostAction($id?'wpnb_test_source_'.$id:'wpnb_save_source');global$wpdb;$input=$id?(array)$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Support::table('sources').' WHERE id=%d LIMIT 1',$id),ARRAY_A):$this->sourceInput();try{$result=(new SourceService($wpdb))->testConnection($input);$detail=sprintf(__('HTTP %1$d, %2$s, %3$d accessible items, %4$d ms','wordpress-news-bot'),$result['http_status'],$result['feed_type'],$result['item_count'],$result['duration_ms']);if(!$id){$token=bin2hex(random_bytes(16));set_transient($this->sourceFormKey(),['input'=>$input,'result'=>$result,'token'=>$token,'input_hash'=>hash('sha256',Support::json($input))],10*MINUTE_IN_SECONDS);}$wpdb->insert(Support::table('logs'),['level'=>'info','event'=>'source_test_succeeded','message'=>'A source connection test succeeded.','context_json'=>Support::json(Security::cleanLogContext($result)),'created_at'=>Support::now()]);$this->storeAdminNotice($detail);if($id)$wpdb->update(Support::table('sources'),['last_checked_at'=>Support::now(),'last_result'=>$detail,'last_error'=>null,'updated_at'=>Support::now()],['id'=>$id]);$this->redirect('wpnb-sources','source_tested');}catch(SourceTestException$e){if(!$id)$this->retainSourceForm($input);if($id)$wpdb->update(Support::table('sources'),['last_checked_at'=>Support::now(),'last_result'=>__('Failed','wordpress-news-bot'),'last_error'=>$this->sourceErrorMessage($e->resultCode),'updated_at'=>Support::now()],['id'=>$id]);$this->handleSourceDiagnostic($e,'source_test_failed');}catch(\Throwable$e){if(!$id)$this->retainSourceForm($input);$this->logSourceError('source_test_failed',$e);$this->redirect('wpnb-sources','source_error');} }
    public function dismissRecovery():void { $this->requirePostAction('wpnb_dismiss_recovery');$recovery=(array)get_option('wpnb_source_recovery_required',[]);if($recovery)update_user_meta(get_current_user_id(),'wpnb_source_recovery_ack',hash('sha256',Support::json($recovery)));$this->redirect('wpnb-sources'); }
    public function toggleSource():void { $id=absint($_POST['source_id']??0);$this->requirePostAction('wpnb_toggle_source_'.$id);global$wpdb;try{(new SourceService($wpdb))->toggle($id);$this->redirect('wpnb-sources','source_toggled');}catch(\Throwable$e){$this->logSourceError('source_toggle_failed',$e);$this->redirect('wpnb-sources','source_error');} }
    public function deleteSource():void { $id=absint($_POST['source_id']??0);$this->requirePostAction('wpnb_delete_source_'.$id);global$wpdb;try{(new SourceService($wpdb))->delete($id);$this->redirect('wpnb-sources','source_deleted');}catch(\Throwable$e){$this->logSourceError('source_delete_failed',$e);$this->redirect('wpnb-sources','source_error');} }
    public function bulkSources():void { $this->requirePostAction('wpnb_bulk_sources');global$wpdb;$ids=array_slice(array_values(array_filter(array_map('absint',(array)($_POST['source_ids']??[])))),0,100);$operation=sanitize_key($_POST['bulk_action']??'');if(!in_array($operation,['activate','deactivate','delete'],true)||!$ids){$this->redirect('wpnb-sources','source_error');}$service=new SourceService($wpdb);try{foreach($ids as$id){if($operation==='delete')$service->delete($id);else$service->toggle($id,$operation==='activate');}$this->redirect('wpnb-sources','bulk_done');}catch(\Throwable$e){$this->logSourceError('source_bulk_failed',$e);$this->redirect('wpnb-sources','source_error');} }
    private function sourceInput():array { return ['name'=>wp_unslash($_POST['name']??''),'feed_url'=>wp_unslash($_POST['feed_url']??''),'allowed_domains'=>wp_unslash($_POST['allowed_domains']??''),'category_id'=>absint($_POST['category_id']??0),'active'=>empty($_POST['active'])?0:1,'import_images'=>empty($_POST['import_images'])?0:1,'draft_without_image'=>empty($_POST['draft_without_image'])?0:1,'use_og_image'=>empty($_POST['use_og_image'])?0:1]; }
    public function pool():void
    {
        global$wpdb;$sourceId=absint($_GET['source_id']??0);$categoryId=absint($_GET['category_id']??0);$status=sanitize_key($_GET['status']??'');$imageStatus=sanitize_key($_GET['image_status']??'');$date=sanitize_text_field(wp_unslash($_GET['date']??''));$search=sanitize_text_field(wp_unslash($_GET['s']??''));$allowedStatuses=['new','review','processing','draft_created','duplicate','skipped','error'];$where=['1=1'];$args=[];
        if($sourceId){$where[]='f.source_id=%d';$args[]=$sourceId;}if($categoryId){$where[]='f.wordpress_category_id=%d';$args[]=$categoryId;}if(in_array($status,$allowedStatuses,true)){$where[]='f.status=%s';$args[]=$status;}if(in_array($imageStatus,['ready','missing','error'],true)){$where[]='f.image_status=%s';$args[]=$imageStatus;}elseif($imageStatus==='without')$where[]='f.image_attachment_id=0';if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$where[]='f.created_at>=%s AND f.created_at<%s';$args[]=$date.' 00:00:00';$args[]=gmdate('Y-m-d H:i:s',strtotime($date.' +1 day'));}if($search!==''){$where[]='(f.title LIKE %s OR f.excerpt LIKE %s)';$like='%'.$wpdb->esc_like($search).'%';$args[]=$like;$args[]=$like;}
        $filterSql=implode(' AND ',$where);$sql='SELECT f.* FROM '.Support::table('feed_items').' f WHERE '.$filterSql.' ORDER BY f.id DESC LIMIT 100';if($args)$sql=$wpdb->prepare($sql,...$args);$rows=$wpdb->get_results($sql);$countSql='SELECT COUNT(*) FROM '.Support::table('feed_items').' f WHERE '.$filterSql;if($args)$countSql=$wpdb->prepare($countSql,...$args);$matching=(int)$wpdb->get_var($countSql);$sources=$wpdb->get_results('SELECT id,name FROM '.Support::table('sources').' ORDER BY name ASC');
        $this->begin(__('News Pool','wordpress-news-bot'));$this->notice();echo '<div class="wpnb-actions">';$this->fetchAllForm(__('Fetch from All Active Sources','wordpress-news-bot'));echo '<a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-sources')).'">'.esc_html__('Go to News Sources','wordpress-news-bot').'</a></div>';
        echo '<form method="get" class="wpnb-card wpnb-actions" style="margin:16px 0"><input type="hidden" name="page" value="wpnb-pool"><select name="source_id"><option value="0">'.esc_html__('All sources','wordpress-news-bot').'</option>';foreach($sources as$source)echo '<option value="'.esc_attr((string)$source->id).'" '.selected($sourceId,(int)$source->id,false).'>'.esc_html((string)$source->name).'</option>';echo '</select>';wp_dropdown_categories(['name'=>'category_id','show_option_all'=>__('All categories','wordpress-news-bot'),'hide_empty'=>0,'selected'=>$categoryId]);echo '<select name="status"><option value="">'.esc_html__('All statuses','wordpress-news-bot').'</option>';foreach($allowedStatuses as$value)echo '<option value="'.esc_attr($value).'" '.selected($status,$value,false).'>'.esc_html($this->poolStatus($value)).'</option>';echo '</select><select name="image_status"><option value="">'.esc_html__('All image statuses','wordpress-news-bot').'</option>';foreach(['ready'=>__('Ready','wordpress-news-bot'),'missing'=>__('Not found','wordpress-news-bot'),'error'=>__('Error','wordpress-news-bot'),'without'=>__('News without images','wordpress-news-bot')]as$value=>$label)echo '<option value="'.esc_attr($value).'" '.selected($imageStatus,$value,false).'>'.esc_html($label).'</option>';echo '</select><input type="date" name="date" value="'.esc_attr($date).'"><input type="search" name="s" value="'.esc_attr($search).'" placeholder="'.esc_attr__('Search','wordpress-news-bot').'"><button class="button">'.esc_html__('Filter','wordpress-news-bot').'</button></form>';
        if(!$rows){echo '<div class="wpnb-card"><h2>'.esc_html__('No news has been fetched yet.','wordpress-news-bot').'</h2><div class="wpnb-actions">';$this->fetchAllForm(__('Fetch from All Active Sources','wordpress-news-bot'));echo '<a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-sources')).'">'.esc_html__('Go to News Sources','wordpress-news-bot').'</a></div></div>';$this->end();return;}
        if(!$this->connected())echo '<div class="notice notice-warning inline"><p>'.esc_html__('Complete the OpenAI connection before creating a draft.','wordpress-news-bot').' <a class="button" href="'.esc_url(admin_url('admin.php?page=wpnb-settings')).'">'.esc_html__('Open Settings','wordpress-news-bot').'</a></p></div>';
        echo '<form id="wpnb-pool-bulk" method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="wpnb-card wpnb-actions">';wp_nonce_field('wpnb_bulk_pool');echo '<input type="hidden" name="action" value="wpnb_bulk_pool"><input id="wpnb-selection-scope" type="hidden" name="selection_scope" value="selected">';foreach(['source_id'=>$sourceId,'category_id'=>$categoryId,'status'=>$status,'image_status'=>$imageStatus,'date'=>$date,'s'=>$search]as$key=>$value)echo '<input type="hidden" name="filter_'.esc_attr($key).'" value="'.esc_attr((string)$value).'">';echo '<select id="wpnb-pool-action" name="bulk_action" required><option value="">'.esc_html__('Bulk actions','wordpress-news-bot').'</option><option value="images">'.esc_html__('Fetch images again','wordpress-news-bot').'</option><option value="draft">'.esc_html__('Create AI drafts','wordpress-news-bot').'</option><option value="queue">'.esc_html__('Add to queue','wordpress-news-bot').'</option><option value="delete">'.esc_html__('Delete from pool','wordpress-news-bot').'</option></select><button class="button button-primary" onclick="if(this.form.bulk_action.value===\'delete\'&&!confirm(\''.esc_js(__('Delete the selected pool items? Existing WordPress posts will be preserved.','wordpress-news-bot')).'\'))return false;">'.esc_html__('Apply','wordpress-news-bot').'</button><span id="wpnb-selection-status">'.esc_html__('No news selected.','wordpress-news-bot').'</span><button id="wpnb-select-filtered" type="button" class="button-link">'.esc_html(sprintf(__('Select all %d news matching the filter.','wordpress-news-bot'),$matching)).'</button><button id="wpnb-clear-selection" type="button" class="button-link">'.esc_html__('Clear selection','wordpress-news-bot').'</button></form><table class="widefat striped wpnb-pool-table"><thead><tr><th class="check-column"><input id="wpnb-select-page" type="checkbox" aria-label="'.esc_attr__('Select all news on this page','wordpress-news-bot').'"></th><th>'.esc_html__('Image','wordpress-news-bot').'</th><th>'.esc_html__('Image status','wordpress-news-bot').'</th><th>'.esc_html__('Title','wordpress-news-bot').'</th><th>'.esc_html__('Source','wordpress-news-bot').'</th><th>'.esc_html__('Source category','wordpress-news-bot').'</th><th>'.esc_html__('WordPress category','wordpress-news-bot').'</th><th>'.esc_html__('Publication date','wordpress-news-bot').'</th><th>'.esc_html__('Fetched date','wordpress-news-bot').'</th><th>'.esc_html__('Status','wordpress-news-bot').'</th><th>'.esc_html__('Actions','wordpress-news-bot').'</th></tr></thead><tbody>';
        foreach($rows as$row){$id=(int)$row->id;$eligible=in_array((string)$row->status,['new','review','error'],true);$category=$row->wordpress_category_id?get_cat_name((int)$row->wordpress_category_id):__('Unassigned','wordpress-news-bot');$preview=(int)$row->image_attachment_id>0?wp_get_attachment_image((int)$row->image_attachment_id,[80,80],false,['loading'=>'lazy']):'—';echo '<tr><th class="check-column"><input class="wpnb-pool-check" data-draft-eligible="'.($eligible?'1':'0').'" form="wpnb-pool-bulk" type="checkbox" name="item_ids[]" value="'.esc_attr((string)$id).'"></th><td>'.$preview.'</td><td>'.esc_html($this->imageStatus((string)$row->image_status)).'</td><td>'.esc_html((string)$row->title).'<details><summary>'.esc_html__('Preview','wordpress-news-bot').'</summary><p>'.esc_html((string)$row->excerpt).'</p></details></td><td>'.esc_html((string)$row->source_name).'</td><td>'.esc_html((string)($row->source_category?:__('Unassigned','wordpress-news-bot'))).'</td><td>'.esc_html($category).'</td><td>'.esc_html((string)($row->published_at?:__('Not provided','wordpress-news-bot'))).'</td><td>'.esc_html((string)$row->created_at).'</td><td>'.esc_html($this->poolStatus((string)$row->status)).'</td><td><div class="wpnb-source-actions"><a class="button" target="_blank" rel="noopener noreferrer" href="'.esc_url((string)$row->source_url).'">'.esc_html__('View at Source','wordpress-news-bot').'</a>';if($eligible)$this->draftForm($id);$this->retryImageForm($id);$this->skipItemForm($id);echo '</div></td></tr>';}
        echo '</tbody></table><script>(()=>{const boxes=[...document.querySelectorAll(".wpnb-pool-check")],all=document.getElementById("wpnb-select-page"),scope=document.getElementById("wpnb-selection-scope"),status=document.getElementById("wpnb-selection-status"),filtered=document.getElementById("wpnb-select-filtered"),clear=document.getElementById("wpnb-clear-selection"),matching='.(int)$matching.';const update=()=>{const count=boxes.filter(box=>box.checked).length;all.checked=count>0&&count===boxes.length;all.indeterminate=count>0&&count<boxes.length;if(scope.value==="filtered")status.textContent="'.esc_js(sprintf(__('All %d news matching the filter are selected.','wordpress-news-bot'),$matching)).'";else status.textContent=count?"'.esc_js(__('This page has %d selected news.','wordpress-news-bot')).'".replace("%d",count):"'.esc_js(__('No news selected.','wordpress-news-bot')).'";};all.addEventListener("change",()=>{scope.value="selected";boxes.forEach(box=>box.checked=all.checked);update();});boxes.forEach(box=>box.addEventListener("change",()=>{scope.value="selected";update();}));filtered.addEventListener("click",()=>{scope.value="filtered";boxes.forEach(box=>box.checked=true);update();});clear.addEventListener("click",()=>{scope.value="selected";boxes.forEach(box=>box.checked=false);update();});update();})();</script>';$this->end();
    }
    private function imageStatus(string$status):string{return match($status){'ready'=>__('Ready','wordpress-news-bot'),'error'=>__('Error','wordpress-news-bot'),default=>__('Not found','wordpress-news-bot')};}
    private function poolStatus(string$status):string{return match($status){'new'=>__('New','wordpress-news-bot'),'review'=>__('Ready for draft','wordpress-news-bot'),'processing'=>__('Processing','wordpress-news-bot'),'draft_created'=>__('Draft created','wordpress-news-bot'),'duplicate'=>__('Duplicate','wordpress-news-bot'),'skipped'=>__('Skipped','wordpress-news-bot'),'error'=>__('Failed','wordpress-news-bot'),default=>$status};}
