    public function fetchSource():void { $id=absint($_POST['source_id']??0);$this->requirePostAction('wpnb_fetch_source_'.$id);try{$result=(new ManualImportService())->importSource($id);$this->storeAdminNotice($this->importSummary($result));$this->redirect('wpnb-sources','source_imported');}catch(\Throwable$e){$this->logSourceError('manual_import_failed',$e);$testId=$e instanceof SourceTestException?$e->testId:bin2hex(random_bytes(8));$this->storeAdminNotice(sprintf(__('Operation ID: %s','wordpress-news-bot'),$testId));$this->redirect('wpnb-sources','source_error');} }
    public function fetchAllSources():void { $this->requirePostAction('wpnb_fetch_all_sources');$offset=absint($_POST['offset']??0);try{$batch=(new ManualImportService())->importAll($offset,5);$lines=array_map(fn(array$result):string=>$this->importSummary($result),$batch['results']);$this->storeAdminNotice(implode(' | ',$lines));$next=$batch['remaining']>0?'&wpnb_import_offset='.($offset+$batch['processed']):'';$this->redirect('wpnb-sources'.$next,'source_imported');}catch(\Throwable$e){$this->logSourceError('manual_import_all_failed',$e);$this->redirect('wpnb-sources','source_error');} }
