    public function skipItem():void { $id=absint($_POST['item_id']??0);$this->requireReviewPostAction('wpnb_skip_item_'.$id);global$wpdb;$wpdb->query('START TRANSACTION');try{$wpdb->delete(Support::table('jobs'),['feed_item_id'=>$id],['%d']);$wpdb->delete(Support::table('ai_generations'),['feed_item_id'=>$id],['%d']);if($wpdb->delete(Support::table('feed_items'),['id'=>$id],['%d'])===false)throw new \RuntimeException();$wpdb->query('COMMIT');$this->redirect('wpnb-pool','item_skipped');}catch(\Throwable){$wpdb->query('ROLLBACK');$this->redirect('wpnb-pool','source_error');} }
    public function createDraft():void { $id=absint($_POST['item_id']??0);$this->requireReviewPostAction('wpnb_create_draft_'.$id);if(!$this->connected())$this->redirect('wpnb-pool','draft_connection');try{$postId=(new DraftService())->create($id);global$wpdb;$imageStatus=(string)$wpdb->get_var($wpdb->prepare('SELECT image_status FROM '.Support::table('feed_items').' WHERE id=%d LIMIT 1',$id));if($imageStatus==='error')$this->storeAdminNotice(__('The draft was created, but its image could not be imported safely. The post remains a draft; you can retry the image from the News Pool.','wordpress-news-bot'));$this->redirect('wpnb-pool&wpnb_post_id='.$postId,'draft_created');}catch(AiOutputRejectedException){$this->storeAdminNotice(__('The AI output did not meet the originality and quality checks. No draft was created.','wordpress-news-bot'));$this->redirect('wpnb-pool','draft_error');}catch(\Throwable){$this->redirect('wpnb-pool','draft_error');} }
