    public function bulkPoolItems():void { $this->requireReviewPostAction('wpnb_bulk_pool');$operation=sanitize_key($_POST['bulk_action']??'');if(!in_array($operation,['images','draft','queue','delete'],true))$this->redirect('wpnb-pool','draft_error');if($operation==='draft'&&!$this->connected())$this->redirect('wpnb-pool','draft_connection');$ids=sanitize_key($_POST['selection_scope']??'selected')==='filtered'?$this->filteredPoolIds($operation):(array)($_POST['item_ids']??[]);$this->finishPoolBulk($ids,$operation); }
